import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import DashboardLayout from "../../layouts/DashboardLayout";
import {
  getAllcoursesWithlessons,
  createCourses,
  updateCourse,
  deleteCourse,
  createVideoLessons,
  updateLesson,
  deleteLesson,
} from "../../api";

export default function Courses() {
  const [courses, setCourses] = useState([]);
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [videoPreview, setVideoPreview] = useState(null);

  const [editingCourse, setEditingCourse] = useState(null);
  const [editingLesson, setEditingLesson] = useState(null);

  const [courseForm, setCourseForm] = useState({ name: "", description: "" });
  const [lessonForm, setLessonForm] = useState({
    title: "",
    description: "",
    videoUrl: "",
    duration: "",
    courseIds: [],
  });

  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [limit] = useState(5);

  useEffect(() => {
    fetchCourses();
  }, [page]);

  const fetchCourses = async () => {
    const res = await getAllcoursesWithlessons(page, limit);
    setCourses(res.data.data);
    setTotalPages(res.data.totalPages);
  };

  const getEmbedUrl = (url) => {
    if (!url) return "";
    if (url.includes("watch?v=")) return url.replace("watch?v=", "embed/");
    if (url.includes("youtu.be/")) {
      const id = url.split("youtu.be/")[1];
      return `https://www.youtube.com/embed/${id}`;
    }
    return url;
  };

  const handleCourseSubmit = async () => {
    if (!courseForm.name) return alert("Name required");

    if (editingCourse) {
      await updateCourse(editingCourse.id, courseForm);
    } else {
      await createCourses(courseForm);
    }

    closeCourseModal();
    fetchCourses();
  };

  const handleLessonSubmit = async () => {
    if (!lessonForm.title || !lessonForm.videoUrl || !lessonForm.courseIds.length)
      return alert("All fields required");

    if (editingLesson) {
      await updateLesson(editingLesson.id, lessonForm);
    } else {
      await createVideoLessons(lessonForm);
    }

    closeLessonModal();
    fetchCourses();
  };

  const handleDeleteCourse = async (id) => {
    if (!window.confirm("Delete course?")) return;
    await deleteCourse(id);
    fetchCourses();
  };

  const handleDeleteLesson = async (id) => {
    if (!window.confirm("Delete lesson?")) return;
    await deleteLesson(id);
    fetchCourses();
  };

  const closeCourseModal = () => {
    setShowCourseModal(false);
    setEditingCourse(null);
    setCourseForm({ name: "", description: "" });
  };

  const closeLessonModal = () => {
    setShowLessonModal(false);
    setEditingLesson(null);
    setLessonForm({
      title: "",
      description: "",
      videoUrl: "",
      duration: "",
      courseIds: [],
    });
  };

  return (
    <DashboardLayout role="admin">
      <div className="p-6">
        <h2 className="text-2xl font-bold mb-6">Course Management</h2>

        <div className="flex gap-3 mb-6">
          <button
            onClick={() => setShowCourseModal(true)}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded"
          >
            + Create Course
          </button>

          <button
            onClick={() => setShowLessonModal(true)}
            className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded"
          >
            + Add Lesson
          </button>
        </div>

        {/* MAIN TABLE */}
        <div className="overflow-x-auto">
          <table className="w-full border border-gray-300 rounded-lg overflow-hidden">
            <thead className="bg-gray-100 text-gray-700">
              <tr>
                <th className="p-3 border">Course Name</th>
                <th className="p-3 border">Description</th>
                <th className="p-3 border text-center">Total Lessons</th>
                <th className="p-3 border">Lessons</th>
                <th className="p-3 border text-center">Actions</th>
              </tr>
            </thead>

            <tbody>
              {courses.length > 0 ? (
                courses.map((course) => (
                  <tr key={course.id} className="hover:bg-gray-50">
                    <td className="p-3 border font-medium">
                      {course.name}
                    </td>

                    <td className="p-3 border">
                      {course.description}
                    </td>

                    <td className="p-3 border text-center font-semibold">
                      {course.lessons?.length || 0}
                    </td>

                    <td className="p-3 border">
                      {course.lessons?.length ? (
                        <div className="max-h-32 overflow-y-auto space-y-2">
                          {course.lessons.map((lesson) => (
                            <div
                              key={lesson.id}
                              className="flex justify-between items-center bg-gray-50 p-2 rounded border"
                            >
                              <div>
                                <p className="font-medium text-sm">
                                  {lesson.title}
                                </p>
                                <p className="text-xs text-gray-500">
                                  {lesson.duration}
                                </p>
                              </div>

                              <div className="flex gap-2">
                                <button
                                  onClick={() =>
                                    setVideoPreview(lesson.videoUrl)
                                  }
                                  className="text-blue-600 text-sm"
                                >
                                  View
                                </button>

                                <button
                                  onClick={() => {
                                    setEditingLesson(lesson);
                                    setLessonForm({
                                      ...lesson,
                                      courseIds: [course.id],
                                    });
                                    setShowLessonModal(true);
                                  }}
                                  className="text-yellow-600 text-sm"
                                >
                                  Edit
                                </button>

                                <button
                                  onClick={() =>
                                    handleDeleteLesson(lesson.id)
                                  }
                                  className="text-red-600 text-sm"
                                >
                                  Delete
                                </button>
                              </div>
                            </div>
                          ))}
                        </div>
                      ) : (
                        <span className="text-gray-400 text-sm">
                          No lessons added
                        </span>
                      )}
                    </td>

                    <td className="p-3 border text-center space-x-2">
                      <button
                        onClick={() => {
                          setEditingCourse(course);
                          setCourseForm(course);
                          setShowCourseModal(true);
                        }}
                        className="bg-yellow-500 hover:bg-yellow-600 text-white px-3 py-1 rounded text-sm"
                      >
                        Edit
                      </button>

                      <button
                        onClick={() =>
                          handleDeleteCourse(course.id)
                        }
                        className="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded text-sm"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="5" className="text-center p-6 text-gray-500">
                    No courses found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* PAGINATION */}
        <div className="flex justify-center gap-3 mt-6">
          <button
            onClick={() => setPage((p) => Math.max(p - 1, 1))}
            disabled={page === 1}
            className="px-4 py-2 border rounded"
          >
            Previous
          </button>

          <span className="px-4 py-2">
            Page {page} of {totalPages}
          </span>

          <button
            onClick={() =>
              setPage((p) => Math.min(p + 1, totalPages))
            }
            disabled={page === totalPages}
            className="px-4 py-2 border rounded"
          >
            Next
          </button>
        </div>

        {/* VIDEO PREVIEW */}
        {videoPreview && (
          <Modal
            title="Video Preview"
            onClose={() => setVideoPreview(null)}
          >
            {videoPreview.includes(".mp4") ? (
              <video controls width="100%">
                <source src={videoPreview} type="video/mp4" />
              </video>
            ) : (
              <iframe
                width="100%"
                height="350"
                src={getEmbedUrl(videoPreview)}
                allowFullScreen
                title="Video"
              />
            )}
          </Modal>
        )}
      </div>
    </DashboardLayout>
  );
}

function Modal({ title, children, onClose }) {
  return createPortal(
    <div
      onClick={onClose}
      className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50"
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="bg-white w-[520px] p-6 rounded-lg"
      >
        <h3 className="mb-4 text-lg font-bold">{title}</h3>
        {children}
      </div>
    </div>,
    document.body
  );
}
